from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    candidates = []
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            candidates.append((Counter(v for line in grid for v in line)[row[0]], "row", r))
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            color = grid[0][c]
            candidates.append((Counter(v for line in grid for v in line)[color], "col", c))

    _, direction, cut = min(candidates)

    if direction == "row":
        a, b = grid[:cut], grid[cut + 1:]
    else:
        a = [row[:cut] for row in grid]
        b = [row[cut + 1:] for row in grid]

    ah, aw = len(a), len(a[0])
    bh, bw = len(b), len(b[0])
    rh, rw = min(ah, bh), min(aw, bw)

    counts_a = Counter(v for row in a for v in row)
    counts_b = Counter(v for row in b for v in row)
    shared = set(counts_a) & set(counts_b)

    # The shared color that matches most often at corresponding positions
    # is the background color used for all non-matching cells.
    base = max(
        shared,
        key=lambda color: sum(
            a[r][c] == color and b[r][c] == color
            for r in range(rh) for c in range(rw)
        )
    )

    return [
        [3 if a[r][c] == b[r][c] else base for c in range(rw)]
        for r in range(rh)
    ]
